<?php
namespace Src\Inventario\Infrastructure\Requests;use Illuminate\Foundation\Http\FormRequest;use Illuminate\Validation\Rule;
class ActualizarRepuestoRequest extends FormRequest{public function authorize():bool{return$this->user()?->can('inventario.gestionar')??false;}protected function prepareForValidation():void{$this->merge(['categoria_id'=>$this->input('categoriaId'),'proveedor_id'=>$this->input('proveedorId')?:null,'codigo'=>mb_strtoupper(trim((string)$this->input('codigo'))),'stock_minimo'=>$this->input('stockMinimo'),'costo_referencia'=>$this->input('costoReferencia'),'precio_venta'=>$this->input('precioVenta')]);}public function rules():array{$id=$this->route('p')?->id;return['categoria_id'=>'required|uuid|exists:categorias_repuesto,id','proveedor_id'=>'nullable|uuid|exists:proveedores,id','codigo'=>['required','max:50',Rule::unique('repuestos')->ignore($id)],'nombre'=>'required|string|max:180','descripcion'=>'nullable|string','unidad'=>['required',Rule::in(['unidad','litro','metro','kilogramo','juego'])],'stock_minimo'=>'required|decimal:0,3|min:0|max:99999999999.999','costo_referencia'=>'required|decimal:0,2|min:0|max:999999999999.99','precio_venta'=>'required|decimal:0,2|min:0|max:999999999999.99'];}}
